architecture.h4_f:
msg = CBOR{v:1, text, reply_to, send_at}
ct = AES-GCM-256-इन्क्रिप्ट(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, text, reply_to?, thread_id?, उल्लेख?, send_at}
ct = AES-GCM-256-इन्क्रिप्ट(room_key, nonce, pt, aad=hex(room_id))
तार = CBOR{
  v: 1,
  सिफरटेक्स्ट: हेक्स(ct), // चर लम्बाइ
  nonce: hex(12 B),
  sender_pseudo: hex(16 B),
  पठाइएको_at: unix_ms
}

cryptoWire.h5_f:
बाहिरी = CBOR{
  source_node: hex32,
  target_user: int64,
  inner_ciphertext: बाइट्स,
  inner_nonce: बाइट्स,
  पठाइएको_at: unix_ms
}
sig = Ed25519-साइन (स्रोत_priv, बाहिरी)
POST /federation/deliver { खाम: बाहिरी, sig: hex64 }

auth.h1_f:
POST /api/authentication/register
  { प्रयोगकर्ता नाम, पासवर्ड, x25519_public_key, display_name, फोन?, इमेल?, avatar_emoji }

प्रतिक्रिया 201 सिर्जना गरियो:
  { access_token, refresh_token, user_id, username, ... }

auth.h3_f:
access_token payload:
  { sub: user_id, jti: device_id, टाइप: "पहुँच", exp: now + 15min }
refresh_token payload:
  { sub: user_id, jti: device_id, टाइप: "रिफ्रेस", exp: now + 30d }

.env बाट नोडको 64-बाइट गोप्यसँग HS256-हस्ताक्षर गरिएको

auth.h4_f:
register_begin(): चुनौती = rand(32)
                    विकल्प = {rp.id, user.id, pubKeyCredParams, चुनौती }
                    फिर्ता विकल्प

register_finish(प्रमाणीकरण):
  TPM / सुरक्षित एन्क्लेभ रूट CA विरुद्ध प्रमाणीकरण प्रमाणित गर्नुहोस्
  स्टोर { credential_id, public_key, काउन्टर: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR पेलोड = { nonce, user_id, सर्भर: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → नयाँ उपकरण दर्ता; JWTs फिर्ता भयो।

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 हेक्स
सिफरटेक्स्ट = AES-GCM-इन्क्रिप्ट(room_key, nonce, CBOR_payload, aad=room_id)

फ्यान-आउट फ्रेम: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {फाइल नाम, आकार, chunk_size_hint}
            ← {upload_id, chunk_size}
खण्ड PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← २०४
अन्तिम रूप दिनुहोस् POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← २०१ {file_id, url}
TTL अधूरोमा: २४ घन्टा

files.h4_f:
अस्वीकार_सूची = {
  "application/x-dosexec",
  "application/x-sharedlib",
  "application/x-mach-binary",
}
if magic.from_buffer(buf[:1024]) in deny_list: फर्काउनुहोस् 415

presence.h1_f:
ग्राहक: पहिलो कीस्ट्रोकमा → पठाउनुहोस् {type:"t", state:"start"}
         राज्य परिवर्तन नभएसम्म 3 s को लागि थप पठाउँदैन
         अन्तिम कीस्ट्रोक पछि 10 सेकेन्ड → पठाउनुहोस् {प्रकार:"t", राज्य:"stop"}
रिसीभर: अन्तिम "सुरु" पछि 10 सेकेन्ड स्वत: रोक्नुहोस् यदि कुनै "स्टप" आइपुगेको छैन

calls.h1_f:
POST /api/calls/{room_id}/start {भिडियो, अडियो} → call_id
WS प्रसारण {प्रकार:"c", प्रकार:"निमन्त्रणा", call_id}
WS प्रसारण {प्रकार:"c", प्रकार:"प्रस्ताव", sdp}
WS प्रसारण {प्रकार:"c", प्रकार:"उत्तर", sdp}
WS प्रसारण {प्रकार:"c", प्रकार:"उम्मेदवार", ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
खाम = {
  source_node : hex32,
  target_user : int64,
  inner_ciphertext: बाइट्स,
  inner_nonce : बाइट्स,
  send_at : unix_ms,
}
sig = Ed25519Sign(स्रोत_priv, CBOR(खाम))
POST /संघ/डिलिभर { लिफाफा, हस्ताक्षर }

stealth.h2_f:
ClientHello बाइट्स = chrome_120_template with {
  यादृच्छिक = हाम्रो अनियमित,
  सर्भर_नाम = हाम्रो होस्टनाम (वा ECH-रेप गरिएको),
  सत्र_आईडी = हाम्रो सत्र आईडी,
}
JA4 = t13d_xxxx_xxxx_xxxx (हालको क्रोम स्थिरसँग मेल खान्छ)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {नाम: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: डोमेन(t) = base32( SHA256(बीज ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(अनुरोध) { decrypt(request.content.userInfo) }
एन्ड्रोइड FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
वेब SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
उपकरण = चिन्ह_उपकरण
इनपुट = स्रोत रूख, कुञ्जी/release.key
प्रकट = {
  संस्करण: "०.१.०",
  बिल्ट_एट: युनिक्स_एमएस,
  फाइलहरू: [{path, sha256, साइज}, ...]
}
sig = Ed25519-साइन(release_priv, CBOR(manifest))
आउटपुट = INTEGRITY.sig.json = {manifest, signed_by: pub_hex, sig: sig_hex}

bots.h1_f:
सिर्जना गर्नुहोस्: POST /api/bots {username, display_name, code}
          → {bot_id, टोकन, pubkey}
रन: इन-प्रोसेस (कोरोटिन भित्र नोड)
      OR बाह्य (लामो-पोल /api/bots/{id}/updates, टोकन-auth'd)
सन्देश: {पाठ, हस्ताक्षर: Ed25519-साइन(bot_priv, canonical_msg)}

bots.h2_f:
on /start {
  emit "स्वागत छ, {ctx.first_name}"
}
मा /add <item> {
  state.list = (state.list वा []) + [ctx.args.item]
  emit "थपिएको: {ctx.args.item}"
}

security.h4_f:
canary.txt (दैनिक):
  {मिति, हस्ताक्षर: Ed25519-Sign(release_priv, date)}
ग्राहक प्रमाणीकरण → अनुपस्थित वा अवैध ⇒ सम्झौता शंकास्पद

आपतकालीन:
  admin POST /api/admin/revoke-all {reason}
  नोड प्रसारण {प्रकार: "n", घटना: "समझौता", कारण}
  क्लाइन्टहरूले कुञ्जीहरू वाइप गर्नुहोस्, बल पुन: बुटस्ट्र्याप गर्नुहोस्

