prekey.h1_f:
बन्डल = {
  identity_pk,
  signed_prekey_pk,
  signed_prekey_sig = Ed25519-साइन(identity_priv, signed_prekey_pk),
  one_time_prekeys: [pk_0, pk_1, ..., pk_9]
}

